mapper.select:
with /**终止登记表：全部内容，条件：封闭式产品、未报送*/ pe as ( select e.* from chb_prd_end_sub e left join chb_prd_baseinfo i on e.prod_id=i.prod_id and i.status!='D' where (e.SUBMIT_FEEDBACK_STATUS !='03' or e.SUBMIT_FEEDBACK_STATUS is null) AND i.RAISE_CCY='CNY' and i.CASH_PRIN_CCY='CNY' AND i.CASH_PROF_CCY='CNY' and i.operate_mode in ('01','02') AND i.VDATE>=date'2014-01-01' and e.MDATE<=#{querydate,jdbcType=DATE} and e.STATUS_DATE<=#{querydate,jdbcType=DATE} and e.status!='04' )
/**产品投资交易：人民币总额，资产持仓数量*/ ,pi as ( select prod_id ,nvl (sum( case when CUR_ASSET_TYPE in('01','03','05','08','10','12') then 0-cny_amt else CNY_AMT end ),0)cny_amt ,nvl (sum( case when CUR_ASSET_TYPE in('01','03','05','06') then num when CUR_ASSET_TYPE in('02','04','07','08') then 0-num else 0 end ),0)asset_qty from chb_invest_trade_sub where status!='04' group by prod_id )
/**产品存续期交易：银行实际收益之和*/ ,pp as ( select prod_id,nvl(sum(BANK_IMP_INT),0) bank_profit from chb_prd_deal_sub where status!='04' group by prod_id )
/**产品的卖出投资交易数量，条件：已报送，卖出交易*/ ,ps as ( select prod_id,count(1) sended_counts from chb_invest_trade_sub where CUR_ASSET_TYPE in ('02','04','07','08') and SUBMIT_FEEDBACK_STATUS = '03' and status!='04' group by prod_id )
/**检查结果*/ select prod_id prodid ,regist_seqno registseqno ,sended_counts regcounts ,abs(1- (total_amt+cny_amt)/ (case when (total_amt+CUSTOM_PROFIT+CUST_FEE_IN+MAN_FEE_IN+COU_FEE_IN+OTHER_FEE_IN+CUST_FEE_OUT)=0 then 1 else total_amt+CUSTOM_PROFIT+CUST_FEE_IN+MAN_FEE_IN+COU_FEE_IN+OTHER_FEE_IN+CUST_FEE_OUT end) ) diffrate1 ,asset_qty holdqty ,cny_amt cashamt ,profit bankprofit1 ,bank_profit bankprofit2 ,CUS_YEAR_YIELD custyield ,PRD_YEAR_YIELD prodyield ,abs( (profit+custom_profit-cny_amt)/(case when cny_amt=0 then 1 else cny_amt end) ) diffrate2 ,custom_profit custprofit1 from ( select ps.sended_counts ,pe.regist_seqno ,pe.prod_id ,nvl(r.total_amt,0) total_amt ,nvl(pi.cny_amt,0) cny_amt ,nvl(pi.asset_qty,0) asset_qty ,nvl(pe.CUSTOM_PROFIT,0) CUSTOM_PROFIT ,nvl(pe.CUST_FEE_IN,0) CUST_FEE_IN ,nvl(pe.MAN_FEE_IN,0) MAN_FEE_IN ,nvl(pe.COU_FEE_IN,0) COU_FEE_IN ,nvl(pe.OTHER_FEE_IN,0) OTHER_FEE_IN ,nvl(pe.CUST_FEE_OUT,0) CUST_FEE_OUT ,nvl(pe.profit,0) profit ,nvl(pp.bank_profit,0) bank_profit ,nvl(pe.CUS_YEAR_YIELD,0) CUS_YEAR_YIELD ,nvl(pe.PRD_YEAR_YIELD,1) PRD_YEAR_YIELD from pe left join ps on pe.prod_id=ps.prod_id left join chb_prd_raisetot_sub r on pe.prod_id=r.prod_id left join pi on pe.prod_id=pi.prod_id left join pp on pe.prod_id=pp.prod_id )

/**未登记的资产*/ with ai as ( select asset_code,count(1) reg_asset_count from chb_asset_info_sub a where a.SUBMIT_FEEDBACK_STATUS ='03' group by asset_code )
,ad as ( select prod_id ,asset_code ,sum( case when CUR_ASSET_TYPE in('01','03','05','06') then nvl(num,0) when CUR_ASSET_TYPE in('02','04','07','08') then 0-nvl(num,0) else 0 end )asset_qty ,round(max(cast(NVL(CNY_AMT, 0) as float)/( case when num=0 then 1 else nvl(num,1) end )),2) max_price ,round(min(cast(NVL(CNY_AMT, 0) as float)/( case when num=0 then 1 else nvl(num,1) end )),2) min_price from chb_invest_trade_sub where (SUBMIT_FEEDBACK_STATUS !='03' or SUBMIT_FEEDBACK_STATUS is null) and STATUS_DATE<=#{querydate,jdbcType=DATE} and status!='04' and CUR_ASSET_TYPE in('01','02','03','04','05','06','07','08') group by prod_id,asset_code )
select ad.asset_code assetcode ,ai.reg_asset_count regcounts ,ad.prod_id prodid ,ad.asset_qty holdqty ,ad.max_price maxprice ,ad.min_price minprice from ad left join ai on ad.asset_code=ai.asset_code

/**未登记的资产*/ with ai as ( select asset_code,count(1) reg_asset_count from chb_asset_info_sub a where a.SUBMIT_FEEDBACK_STATUS ='03' group by asset_code )
,ad as ( select p.regist_seqno ,p.asset_code ,i.vdate ,i.mdate ,p.pos_date ,round( nvl(p.ISSUE_AMT,0)/( case when (nvl(sp.POS_AMT,0)+nvl(p.UNINVEST_CASH,0))=0 then 1 else (nvl(sp.POS_AMT,0)+nvl(p.UNINVEST_CASH,0)) end ) ,2)diff_value from chb_bot_ast_pos_sub p left join ( select sum(POS_AMT) POS_AMT,PLAN_ASSET_ID from chb_bot_ast_pos_sub GROUP by PLAN_ASSET_ID ) sp on sp.PLAN_ASSET_ID=p.PLAN_ASSET_ID left join chb_asset_info_sub i on p.asset_code=i.asset_code and i.SUBMIT_FEEDBACK_STATUS ='03' where (p.SUBMIT_FEEDBACK_STATUS !='03' or p.SUBMIT_FEEDBACK_STATUS is null) and p.STATUS_DATE<=#{querydate,jdbcType=DATE}
)
select ad.asset_code assetcode ,ad.regist_seqno registseqno ,ad.vdate vdate ,ad.mdate mdate ,ad.pos_date posdate ,ad.diff_value diffrate1 ,ai.reg_asset_count regcounts from ad left join ai on ad.asset_code=ai.asset_code
